import workcell, time
names=["B1","B2","B3","B4","fixture"]
acc={n:[0,0,0] for n in names}
N=6
for i in range(N):
    for n in names:
        r=workcell.call("robot","locate",n)
        d=r.data
        if n=="fixture":
            x,y=d["x"],d["y"]
        else:
            x,y=d["x"],d["y"]
        acc[n][0]+=x; acc[n][1]+=y; acc[n][2]+=1
        print(i,n,x,y)
for n in names:
    print(n, acc[n][0]/acc[n][2], acc[n][1]/acc[n][2])
PY

